<script>
const catalog=@json($catalog),previousItems=@json($oldItems),models={
'Lelaki Pendek':{sleeve:'short',label:'Lengan pendek',image:@json(asset('images/jersey/model-pria-pendek-v2.jpg'))},
'Lelaki Panjang':{sleeve:'long',label:'Lengan panjang',image:@json(asset('images/jersey/model-pria-panjang-v3.jpg'))},
'Muslimah':{sleeve:'long',label:'Lengan panjang',image:@json(asset('images/jersey/model-muslimah-v3.jpg'))}};
const container=document.getElementById('order-items'),money=v=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(v);
function options(rows,selected){return rows.map(row=>`<option value="${row.id}" ${String(row.id)===String(selected)?'selected':''}>${row.name}</option>`).join('')}
function addItem(data={}){if(container.children.length>=20)return;const product=catalog.find(p=>String(p.id)===String(data.jersey_product_id))||catalog[0],size=product.sizes.find(s=>String(s.id)===String(data.jersey_size_id))||product.sizes[0],model=models[data.model]?data.model:'Lelaki Pendek',quantity=Math.max(1,Math.min(20,Number(data.quantity)||1)),card=document.createElement('article');card.className='order-item overflow-hidden rounded-3xl bg-white shadow-lg';card.innerHTML=`<div class="grid md:grid-cols-[180px_1fr]"><div class="bg-emerald-50 p-4"><img data-role="image" src="${models[model].image}" alt="${model}" class="aspect-square w-full rounded-2xl object-cover"></div><div class="p-5 md:p-6"><div class="flex items-center justify-between gap-3"><h3 class="text-xl font-black">Jersey <span data-role="number"></span></h3><button type="button" data-action="remove" class="text-sm font-bold text-red-700">Hapus</button></div><div class="mt-4 grid gap-4 md:grid-cols-2"><label class="font-bold">Model<select data-role="model" class="mt-2 w-full rounded-xl border p-3">${Object.keys(models).map(name=>`<option ${name===model?'selected':''}>${name}</option>`).join('')}</select></label><label class="font-bold">Produk<select data-role="product" class="mt-2 w-full rounded-xl border p-3">${options(catalog,product.id)}</select></label><label class="font-bold">Ukuran<select data-role="size" class="mt-2 w-full rounded-xl border p-3">${options(product.sizes,size?.id)}</select></label><label class="font-bold">Jumlah<input data-role="quantity" type="number" min="1" max="20" value="${quantity}" class="mt-2 w-full rounded-xl border p-3"></label></div><div class="mt-4 flex items-center justify-between rounded-xl bg-slate-50 p-4"><span data-role="sleeve" class="text-sm text-slate-600"></span><b data-role="subtotal"></b></div>${['product','size','model','sleeve','quantity'].map(field=>`<input data-field="${field}" type="hidden">`).join('')}</div></div>`;container.appendChild(card);bind(card);sync(card);reindex()}
function bind(card){card.querySelector('[data-role="model"]').onchange=()=>sync(card);card.querySelector('[data-role="product"]').onchange=()=>{const p=catalog.find(x=>String(x.id)===card.querySelector('[data-role="product"]').value);card.querySelector('[data-role="size"]').innerHTML=options(p.sizes,p.sizes[0]?.id);sync(card)};card.querySelector('[data-role="size"]').onchange=()=>sync(card);card.querySelector('[data-role="quantity"]').oninput=()=>sync(card);card.querySelector('[data-action="remove"]').onclick=()=>{if(container.children.length===1)return;card.remove();reindex();total()}}
function sync(card){const modelName=card.querySelector('[data-role="model"]').value,productId=card.querySelector('[data-role="product"]').value,sizeId=card.querySelector('[data-role="size"]').value,q=card.querySelector('[data-role="quantity"]'),product=catalog.find(p=>String(p.id)===productId),size=product.sizes.find(s=>String(s.id)===sizeId),model=models[modelName];q.value=Math.max(1,Math.min(20,Number(q.value)||1));card.querySelector('[data-role="image"]').src=model.image;card.querySelector('[data-role="image"]').alt=modelName;card.querySelector('[data-role="sleeve"]').textContent=model.label;card.querySelector('[data-role="subtotal"]').textContent=money((product.price+Number(size?.adjustment||0))*Number(q.value));card.querySelector('[data-field="product"]').value=productId;card.querySelector('[data-field="size"]').value=sizeId;card.querySelector('[data-field="model"]').value=modelName;card.querySelector('[data-field="sleeve"]').value=model.sleeve;card.querySelector('[data-field="quantity"]').value=q.value;total()}
function reindex(){const names={product:'jersey_product_id',size:'jersey_size_id',model:'model',sleeve:'sleeve',quantity:'quantity'};[...container.children].forEach((card,i)=>{card.querySelector('[data-role="number"]').textContent=i+1;card.querySelector('[data-action="remove"]').classList.toggle('invisible',container.children.length===1);Object.keys(names).forEach(field=>card.querySelector(`[data-field="${field}"]`).name=`items[${i}][${names[field]}]`)})}
function total(){let amount=0,count=0;[...container.children].forEach(card=>{const p=catalog.find(x=>String(x.id)===card.querySelector('[data-role="product"]').value),s=p.sizes.find(x=>String(x.id)===card.querySelector('[data-role="size"]').value),q=Number(card.querySelector('[data-role="quantity"]').value)||1;amount+=(p.price+Number(s?.adjustment||0))*q;count+=q});document.getElementById('grand-total').textContent=money(amount);document.getElementById('item-summary').textContent=`${count} jersey dalam ${container.children.length} item`}
document.getElementById('add-item').onclick=()=>addItem();(previousItems.length?previousItems:[{}]).forEach(addItem);
</script>
